const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;

if (!API_BASE_URL) {
  throw new Error("NEXT_PUBLIC_API_BASE_URL is not defined");
}

export async function getRestaurants(params: string = "") {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 5000);

  try {
    const res = await fetch(
      `${process.env.NEXT_PUBLIC_API_BASE_URL}/restaurants${params}`,
      {
        cache: "no-store",
        signal: controller.signal,
      }
    );

    if (!res.ok) {
      const text = await res.text();
      throw new Error(text);
    }

    return res.json();
  } finally {
    clearTimeout(timeout);
  }
}


export async function getRestaurant(id: string) {
  const res = await fetch(`${API_BASE_URL}/restaurants/${id}`, {
    cache: "no-store",
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Failed to fetch restaurant: ${text}`);
  }

  return res.json();
}

export async function getProducts(restaurantId: string) {
  const res = await fetch(
    `${API_BASE_URL}/restaurants/${restaurantId}/products`,
    { cache: "no-store" }
  );

  if (!res.ok) {
    throw new Error("Failed to fetch products");
  }

  return res.json();
}
